SELECT
FROM t_novel n LEFT JOIN t_user u ON u.id = n.user_id
AND n.deleted = #{deletedFlag}
AND (LOWER(n.title) LIKE LOWER(CONCAT('%', #{q.keyword}, '%')) OR LOWER(u.username) LIKE LOWER(CONCAT('%', #{q.keyword}, '%')) OR LOWER(u.nickname) LIKE LOWER(CONCAT('%', #{q.keyword}, '%')))
AND n.status IN
#{item}
AND n.created_at >= #{q.createdFrom}
AND n.created_at < #{q.createdToExclusive}
ORDER BY n.updated_at DESC, n.id DESC
ORDER BY n.word_count DESC, n.id DESC
ORDER BY n.chapter_count DESC, n.id DESC
ORDER BY n.created_at DESC, n.id DESC

SELECT id, novel_id, volume_no, volume_title, chapter_no, title, summary, word_count, status, deleted, created_at, updated_at FROM t_chapter WHERE novel_id = #{novelId}
AND deleted = 0
ORDER BY sort_no ASC, chapter_no ASC

mapper.update:
UPDATE t_book_digest
SET generated_novel_id = NULL
WHERE generated_novel_id = #{novelId}
